<h1 class="page-title">ปฏิทินติดตามงาน</h1>
<form id="calendar-filters" class="row g-2 mb-3"><div class="col-sm-3"><select name="type" class="form-select" aria-label="ประเภทงาน"><option value="">ทุกประเภท</option><option value="CORRECTIVE">งานซ่อม</option><option value="PREVENTIVE">PM</option></select></div><div class="col-sm-3"><select name="status" class="form-select" aria-label="สถานะ"><option value="">ทุกสถานะ</option><?php foreach(\App\Models\TicketStatus::LABELS as $k=>$v): ?><option value="<?= e($k) ?>"><?= e($v) ?></option><?php endforeach ?></select></div><div class="col-sm-3"><select name="priority_id" class="form-select" aria-label="ความเร่งด่วน"><option value="">ทุกความเร่งด่วน</option><?php foreach($priorities as $p): ?><option value="<?= e($p['id']) ?>"><?= e($p['name_th']) ?></option><?php endforeach ?></select></div><div class="col-sm-3"><select name="category_id" class="form-select" aria-label="หมวดงาน"><option value="">ทุกหมวดงาน</option><?php foreach($categories as $c): ?><option value="<?= e($c['id']) ?>"><?= e($c['name_th']) ?></option><?php endforeach ?></select></div></form>
